"""Utilities for checking whether bracket sequences are balanced."""


def balanced(s: str) -> bool:
    """Return whether brackets in *s* are balanced and correctly ordered.

    Characters inside double-quoted strings are ignored. Within a string, a
    backslash escapes the following character. An unterminated string makes the
    input unbalanced.
    """
    opening_for = {')': '(', ']': '[', '}': '{'}
    stack: list[str] = []
    in_string = False
    escaped = False

    for char in s:
        if in_string:
            if escaped:
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '"':
                in_string = False
            continue

        if char == '"':
            in_string = True
        elif char in '([{':
            stack.append(char)
        elif char in opening_for:
            if not stack or stack.pop() != opening_for[char]:
                return False

    return not in_string and not stack
